<?php
require_once __DIR__.'/../backend/rutas_aprendizaje.php';
$pfTipoRuta=$pfTipoRuta??'';$pfContenidoRutaId=(int)($pfContenidoRutaId??0);$pfUsuarioRuta=$pfUsuarioRuta??current_user();
$pfRutasContenido=rutas_de_contenido($conn,$pfTipoRuta,$pfContenidoRutaId,true);$pfSlugRuta=trim($_GET['ruta']??'');$pfRutaActiva=null;
foreach($pfRutasContenido as $r){if($r['slug']===$pfSlugRuta){$pfRutaActiva=$r;break;}}
if($pfRutaActiva){$pfItemsRuta=ruta_items($conn,(int)$pfRutaActiva['id']);$pfIndice=0;foreach($pfItemsRuta as $k=>$it){if($it['tipo_contenido']===$pfTipoRuta&&(int)$it['contenido_id']===$pfContenidoRutaId){$pfIndice=$k;break;}}if($pfUsuarioRuta)ruta_marcar_activa($conn,(int)$pfUsuarioRuta['id'],(int)$pfRutaActiva['id'],(int)$pfItemsRuta[$pfIndice]['id']);$pfAnterior=$pfItemsRuta[$pfIndice-1]??null;$pfSiguiente=$pfItemsRuta[$pfIndice+1]??null;}
$pfSugerido=$pfRutaActiva?null:contenido_siguiente_sugerido($conn,$pfTipoRuta,$pfContenidoRutaId);
?>
<?php if($pfRutaActiva):?><div class="alert d-flex flex-wrap align-items-center gap-2 mb-4" style="background:#fff8ec;border:1px solid #f0c58f"><strong>Ruta: <?=htmlspecialchars($pfRutaActiva['titulo'])?></strong><span class="text-muted">Paso <?=$pfIndice+1?> de <?=count($pfItemsRuta)?></span><a class="ms-auto" href="?action=ruta&slug=<?=urlencode($pfRutaActiva['slug'])?>">Volver al mapa</a><?php if($pfAnterior):?><a class="btn btn-sm btn-outline-secondary" href="?action=<?=$pfAnterior['tipo_contenido']?>&slug=<?=urlencode($pfAnterior['slug'])?>&ruta=<?=urlencode($pfRutaActiva['slug'])?>">← Anterior</a><?php endif;?><?php if($pfSiguiente):?><a class="btn btn-sm" style="background:#f7931e;color:#fff" href="?action=<?=$pfSiguiente['tipo_contenido']?>&slug=<?=urlencode($pfSiguiente['slug'])?>&ruta=<?=urlencode($pfRutaActiva['slug'])?>">Siguiente →</a><?php endif;?></div>
<?php elseif($pfRutasContenido):?><div class="alert alert-light border mb-4">Este contenido forma parte de <?php foreach(array_slice($pfRutasContenido,0,2) as $k=>$r):?><?=$k?', ':''?><a href="?action=ruta&slug=<?=urlencode($r['slug'])?>"><?=htmlspecialchars($r['titulo'])?></a><?php endforeach;?>.</div><?php endif;?>
<?php if($pfSugerido):?><div class="card border-0 shadow-sm p-3 mb-4"><span class="small text-muted">Contenido sugerido siguiente</span><div class="d-flex justify-content-between align-items-center gap-2"><strong><?=htmlspecialchars($pfSugerido['titulo'])?></strong><a class="btn btn-sm btn-outline-secondary" href="?action=<?=$pfSugerido['destino_tipo']?>&slug=<?=urlencode($pfSugerido['slug'])?>">Conocer contenido →</a></div></div><?php endif;?>
